  `status` enum('menunggu','dipanggil','selesai','batal') NOT NULL DEFAULT 'menunggu',
  `lanjut_ke_tindakan` tinyint(1) DEFAULT NULL COMMENT 'Diisi HANYA pada antrian bertipe konsultasi saat petugas menyelesaikan sesi: 1 = pasien lanjut ke tindakan (sistem auto-generate baris antrian tindakan baru dgn kode_antrian_asal = antrian ini); 0/NULL = konsultasi berdiri sendiri, data cukup tersimpan di rekam medis.',
  `dipanggil_at` timestamp NULL DEFAULT NULL,
  `selesai_at` timestamp NULL DEFAULT NULL,
  `tz` varchar(50) NOT NULL DEFAULT 'UTC',
  `created_by` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` varchar(100) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `hasil_form` text
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

