--

CREATE TABLE `trx_detail_antrian_layanan` (
  `id` int UNSIGNED NOT NULL,
  `kode_detail_antrian_layanan` varchar(30) NOT NULL,
  `kode_antrian_layanan` varchar(30) NOT NULL,
  `kode_kunjungan` varchar(30) NOT NULL,
  `jenis_layanan` varchar(20) DEFAULT 'layanan',
  `kode_layanan` varchar(50) NOT NULL,
  `nama_layanan` varchar(255) NOT NULL,
  `harga` decimal(15,2) DEFAULT '0.00',
  `kode_promo` varchar(30) DEFAULT NULL,
  `nama_promo` varchar(100) DEFAULT NULL,
  `jenis_diskon` varchar(20) DEFAULT NULL,
  `nilai_diskon` decimal(10,2) DEFAULT '0.00',
  `kode_ruangan` varchar(20) DEFAULT NULL,
  `nama_ruangan` varchar(100) DEFAULT NULL,
  `tz` varchar(50) DEFAULT 'Asia/Jakarta',
  `created_by` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` varchar(100) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

